const MERCHANT_LEVEL_4_QUESTIONS: MerchantLevelQuestion[] = [
  { ref: "L4.1", text: "Confirm annual transaction and e-commerce volumes place the merchant at Level 4, and that the transaction volume is reassessed at least annually.", pciRequirement: "12.5" },
  { ref: "L4.2", text: "Confirm the smallest SAQ the merchant is eligible for has been identified with the acquirer (SAQ A, SAQ A-EP, SAQ B, SAQ B-IP, or SAQ D) and the eligibility rationale is documented.", pciRequirement: "12.5" },
  { ref: "L4.3", text: "If cardholder data is fully outsourced to a PCI DSS compliant service provider, confirm a written agreement exists and the provider's AoC covers every cardholder data function the merchant outsources.", pciRequirement: "12.8, 12.9" },
  { ref: "L4.4", text: "Confirm the merchant retains responsibility for the cardholder data functions it performs itself, and that the division of responsibilities is documented in the responsibility matrix.", pciRequirement: "12.8.2" },
  { ref: "L4.5", text: "Confirm any system components in the merchant's own CDE have network security controls and secure configurations in place, with no vendor default accounts or passwords.", pciRequirement: "1.2, 2.2" },
  { ref: "L4.6", text: "Confirm sensitive authentication data is never retained after authorization, and PAN is either not stored or rendered unreadable.", pciRequirement: "3.3, 3.5" },
  { ref: "L4.7", text: "Confirm cardholder data transmitted over open, public networks is protected with TLS 1.2 or stronger and that insecure protocols are disabled.", pciRequirement: "4.2" },
  { ref: "L4.8", text: "Confirm each user with access to the CDE has a unique identity, and multi-factor authentication is used wherever access is interactive or administrative.", pciRequirement: "8.2, 8.3, 8.4" },
  { ref: "L4.9", text: "Confirm external vulnerability scans by an approved ASV are performed at least every four months and after any significant change, with passing rescan reports retained for 12 months.", pciRequirement: "11.3.2" },
  { ref: "L4.10", text: "Confirm segmentation used to reduce PCI DSS scope is tested at least annually per Req 11.4.5 (or at the more frequent cadence required by the acquirer), or that the merchant does not rely on segmentation to reduce scope.", pciRequirement: "11.4.5" },
  { ref: "L4.11", text: "Confirm the information security policy is maintained, published, and acknowledged annually, and that all personnel complete security awareness training at least annually.", pciRequirement: "12.1, 12.6" },
  { ref: "L4.12", text: "Confirm a documented and tested incident response plan exists for suspected cardholder data breaches, with the required notification timelines defined.", pciRequirement: "12.10" },
  { ref: "L4.13", text: "Confirm the Attestation of Compliance is signed by an executive officer and the completed SAQ plus AoC are submitted to the acquirer annually, with acknowledgements retained.", pciRequirement: "12.9" },
];

